#include <stdio.h>
#include <stdlib.h>

struct node { int v; struct node *next; };

int sum_list(const struct node *h) {      // null marks the end
    int s = 0;
    for (; h != NULL; h = h->next) s += h->v;
    return s;
}

void greet(const char *name) {            // NULL means "no name given"
    if (name == NULL) { puts("Hello, stranger"); return; }
    printf("Hello, %s\n", name);
}

int main(void) {
    int *buf = malloc(5 * sizeof *buf);
    if (buf == NULL) {                     // allocation can fail
        fputs("out of memory\n", stderr);
        return 1;
    }
    buf[0] = 7;
    free(buf);
    buf = NULL;                            // never leave a dangling pointer
    greet(NULL);
    return 0;
}

int *grow(int *a, size_t n) {
    int *t = realloc(a, n * sizeof *t);
    if (t == NULL) return NULL;    // old block still valid and owned by caller
    return t;
}

int bad(int *p) {
    int v = *p;          // UB if p is NULL
    if (p == NULL)       // compiler may drop this test
        return -1;
    return v;
}

struct node *find(struct node *h, int key) {
    while (h != NULL && h->v != key)    // order matters: test null first
        h = h->next;
    return h;                            // NULL when not found
}

#define FREE_AND_NULL(p) do { free(p); (p) = NULL; } while (0)

char *s = strdup("data");
FREE_AND_NULL(s);
FREE_AND_NULL(s);       // safe, free(NULL) does nothing
